  ya = `Denne begivenheten publiseres automatisk på angitt tidspunkt. Begivenheter av denne typen kan IKKE publiseres før starttidspunktet.`,
  ba = `Hvis begivenheten publiseres, blir alle endringene lagret og begivenheten blir synlig i henhold til synlighetsinnstillingene.`,
  xa = `Publiser som ikke oppført`,
  Sa = `Å publisere begivenheten lagrer eventuelle endringer og gjør begivenheten synlig for de som har lenke til begivenheten. Denne begivenheten dukker ikke opp i listen over begivenheter, men kunder kan se den hvis de har lenken.`,
  Ca = `Publiser`,
  wa = `Å publisere siden lagrer eventuelle endringer og gjør skapersiden synlig for de som har lenke til den. Kunder kan se den hvis de har lenken. For å gjøre dette til den gjeldende skapersiden må du aktivere den etter publisering.`,
  Ta = `Er du klar til å lagre endringene og deretter publisere begivenheten?`,
  Ea = `Begivenheten blir umiddelbart synlig offentlig.`,
