  Oa = `  Du kan fremdeles redigere innholdet i begivenheten etter publiseringen.`,
  ka = `Merk: Når begivenheten først er publisert, kan du ikke gjøre om publiseringen.`,
  Aa = `Er du klar til å lagre endringene og publisere denne siden?`,
