  Ma = `Du kan fortsette å redigere siden etter publiseringen.`,
  Na = `(Valve) Fordi denne gruppen har et tilordnet Crowdin-prosjekt, gjør publisering det mulig å sende oppdateringer til Crowdin automatisk. Du kan slå det av igjen manuelt når som helst.`,
  Pa = `Tilpasset publiseringstidspunkt`,
