  Ra = `Kan ikke publisere før Valve har godkjent`,
  za = `Bruk knappen til høyre for å sende inn siden din til gjennomgang minst 7 dager før planlagt publiseringsdato, slik at det er god nok tid til å gå gjennom og godkjenne, og gjøre eventuelle nødvendige endringer.`,
  Ba = `Intern feil i redigeringen. Vi kunne ikke laste inn lokaliseringsteksten, blokkerer lagre/publiser for å forhindre datatap.`,
  Va = `Advarsel: Innholdet i denne begivenheten eller kunngjøringen ble endret kl. %1$s av %2$s. Versjonen som du begynte å redigere, er fra kl. %3$s. Vil du overskrive disse endringene?`,
