  $a = `Etter at du publiserer begivenheten, så forblir den skjult inntil dette tidspunktet. Dette lar deg forberede flere begivenheten i fremtiden og få dem til å vises automatisk ved det angitte tidspunktet, og gi kundene en stadig strøm av interessante aktiviteter.`,
