  So = `Rediger/overfør`,
  Co = `Denne kunngjøringen ble opprettet i en tidligere versjon av systemet. Den vil ikke ha de nye kategoriene, tittelbildet og en sluttdato. Hvis du redigerer og deretter lagrer, overføres den til det nye systemet, så du kan bruke de nye funksjonene.`,
  wo = `Dette sletter begivenheten fra Steam og fjerner all dens metadata (stemmer, kommentarer, statistikk). Hvis begivenheten allerede er synlig, omdirigerer den til en tom side og anbefales ikke til kunder. Denne handlingen kan ikke angres.`,
