  qo = `Opptil %1$s tegn uten noe BBCode. Denne beskrivelsen vises i Steam-biblioteket. Det korte beskrivelsesfeltet er valgfritt. Hvis det ikke fylles ut, genereres det automatisk fra den første tekstparagrafen i begivenhetens beskrivelse.`,
