  es = `Sammendraget kan være på opptil %1$s tegn, og kun tekst. Sammendraget vises nedenfor tittelen, når begivenheten vises i en liste eller i begivenhetens fremhevede område. Hvis det ikke fylles ut et sammendrag, genererer Steam det automatisk ved å hente tekst fra begynnelsen av beskrivelsen for hvert språk.`,
