  fs = `Vis som en fremhevet begivenhet på spillsiden i biblioteket`,
  ps = `Før vi kan bruke det fremhevede området, må du sørge for at vi har det engelske fremhevede bildet satt opp i fanen «%1$s».`,
  ms = `Vis automatisk tekst?`,
  hs = `Begivenhetens overskrift og underoverskrift, sammen med et formørket overlegg, legges automatisk over høyre side av bildet.`,
  gs = `Denne begivenheten blir midlertidig fremhevet ovenfor aktivitetsseksjonen for hver bruker. Dette bør bare brukes til store begivenheter, med tilstrekkelig tid mellom begivenhetene, slik at det ikke alltid fremheves en begivenhet på spillets bibliotekside.`,
