  bs = `Vis på produktsiden i Steam-butikken`,
  xs = `Tenk over innholdet som vises for Steam-brukere som har spillet i deres bibliotek, og for brukere som besøker produktsiden i butikken. Det er for eksempel ikke tillatt å inkludere en lenke til en annen butikk der spillet kan kjøpes. Du bør også følge %1$s.`,
