  Xs = `Hvis bakgrunnsfargen til bakgrunnsbildet er veldig lys, kan det være vanskelig å se pilen. Bruk denne innstillingen for å overstyre den hvite standardfargen til karusellpilene.`,
  Zs = `Hvis bakgrunnsfargen eller bakgrunnsbildet har veldig lys farge, kan det være vanskelig å se pilen. Bruk denne innstillingen for å overstyre den hvite og grå standardfargen til karusellens brødsmuler.  Dette vises hovedsakelig for mindre skjermer, deriblant Steam Deck.`,
