  ec = `Begivenheten må lagres for å kunne deles med demoen.`,
  tc = `Begivenheten/kunngjøring vises på demoens bibliotekside når den er publisert. Gjør det mulig å kommunisere med spillere som kun har demoen. `,
  nc = `Temabegivenheter: %1$s`,
  rc = `Halloween 2022`,
  ic = `Handler begivenheten om oppdateringer til spillet for halloween 2022? Hvis du legger til nye kart, drakter, kunst, eller annet innhold i spillet for halloween, eller kjører tidsbegrensede begivenheter med spesielt skummelt innhold, utfordringer eller andre lignende aktiviteter, vil vi gjerne høre om det. Vi vurderer forskjellige måter å bedre vise temabegivenheter til et større publikum, men først må vi vite mer om hva slags aktiviteter utviklere eventuelt arrangerer i spillene deres for å feire høytiden. Trykk «på» nedenfor, hvis denne begivenheten handler om en oppdatering til spillet for halloween 2022.`,
  ac = `Halloweenbegivenheter`,
  oc = `Kjører du en begivenhet eller legger du til innhold med halloweentema? Ta en titt på %1$s for å finne ut mer om å delta i Steam Scream med halloweenbegivenheter i spill.`,
