  lc = `Permanent utvidelse med halloweentema til spillet ditt`,
  uc = `Kunngjør en tidsbegrenset halloweenbegivenhet i spillet, som kan gi spillerne ekstra gjenstander, bonuser, fordeler, belønninger, XP osv. Disse har et start- og sluttidspunkt.`,
  dc = `Kategori til Steam-prisnominasjoner`,
  fc = `Velg en spesifikk kategori som fansene dine kan nominere spillet til. De kan nominere spillet ditt til kategorien i selve begivenheten!`,
  pc = `De fleste kategoriene til Steam-prisen i år er til spill som er utgitt i %1$s (etter nominasjoner til den forrige Steam-prisen %2$s). Siden spillet ditt ble utgitt før denne datoen, kan det kun nomineres i kategorien «Laget med kjærlighet».`,
  mc = `For mer informasjon og for å laste ned ressurspakken for Steam-prisen med designmaler du kan bruke i markedsføring, gå til <1>dokumentasjonen her</1>.`,
  hc = `Dette spillet oppfyller ikke kravene til noen av kategoriene til Steam-prisen. Hvis du mener dette er feil, ta kontakt med <1>kundestøtten i Steamworks</1>.`,
  gc = `Bekreftelse på usynlig butikkside`,
  _c = `Butikksiden til app-ID %1$s er ikke synlig for øyeblikket. Brukere får vite om spillet når du publiserer denne begivenheten. Hvis du velger å publisere denne begivenheten likevel, må du eksplisitt bekrefte det her.`,
