  ll = `Butikkapsler`,
  ul = `Disse kapslene lar butikken fremheve denne salgssiden på steder der den vanligvis fremhever spill: karusellen for aktuelt og anbefalt, butikksentralene og handlevognen. Det er de samme kapslene som et spill laster opp under grafiske elementer på butikksiden, i samme størrelser.`,
  dl = `Du kan laste opp alle på en gang. Et bilde tilordnes en kapsel automatisk hvis størrelsen stemmer nøyaktig overens med kapselen, ellers må du tilordne selv, og du blir bedt om å beskjære det. Du kan navngi bildefilene så de ender på et språknavn for at de skal kategoriseres som det språket (for eksempel «main_capsule_french.jpg»).`,
  fl = `Fokuser på salgets merkevare. Sørg for at logoen er tydelig.`,
