  Il = `Skriv kun inn den delen av adressen som følger butikkens hjemmeside, uten ledende skråstrek. For eksempel category/pins_pegs for å lenke til https://store.steampowered.com/category/pins_pegs.`,
  Ll = `Dette må være relativt til butikkens hjemmeside, så ikke ta med den ledende https://store.steampowered.com/. For eksempel category/pins_pegs i stedet for https://store.steampowered.com/category/pins_pegs.`,
