  Au = `Merk: Hvis du har flere språk, så får du kanskje en advarsel fra nettleseren om at vi prøver å laste ned flere filer. Du kan trygt tillate dette, da det skyldes at vi lagrer hvert språk i sin egen XML-fil.`,
