  Ru = `Importer …`,
  zu = `Velg én eller flere filer du vil laste opp for å importere lokalisert tekst for tittel, undertittel, sammendrag og beskrivelse. Vi bruker filtypen til å fastslå om filen er en XML- eller CSV-import; til XML bruker vi API-språkkoden sist i filnavnet, før filtypen, til å fastslå språket på innholdet i XML-filen. Du bør starte med å eksportere CSV- eller XML-filen for å sikre at du bruker riktig format.`,
