  xd = `Begivenhetens starttidspunkt er ikke angitt.`,
  Sd = `Begivenhetens starttidspunkt (%1$s) er i fortiden. Du må enten justere starttidspunktet til i fremtiden eller nå. Hvis du kunne publisert i fortiden, så kunne brukere som nylig har besøkt siden gått glipp av begivenheter, siden deres besøk ville vært etter at begivenheten hadde startet.`,
