  Ed = `Det nåværende synlighetstidspunktet er etter begivenhetens starttidspunkt, noe som forhindrer den fra å bli synlig når den starter.`,
  Dd = `Beskrivelsen kan maks være på 32 000 tegn. Beskrivelsen på %1$s er lengre enn 32 000 tegn.`,
