  Ld = `Fanen %1$s mangler %2$s av %3$s påkrevde felt.`,
  Rd = `Det følgende er advarsler for den aktuelle begivenheten som du kan omgå og ikke forhindrer publisering, men vi anbefaler at du retter dem opp.`,
  zd = `Mangler enten begivenhetens beskrivelse og/eller navn på engelsk. Engelsk er hoved- eller reservespråket for mange Steam-brukere. Uten det vil begivenhetens synlighet for Steam-kunder være meget begrenset.`,
  Bd = `Bilde mangler. Begivenheter tillater tilpassede bilder som hjelper med å markedsføre begivenheten og trekke til seg Steam-brukeres oppmerksomhet. Hvis det ikke finnes et bilde, bruker vi spillets kapselbilde i stedet.`,
  Vd = `Bilde mangler. Begivenheter tillater tilpassede bilder som hjelper med å markedsføre begivenheten og trekke til seg Steam-brukeres oppmerksomhet. Hvis det ikke finnes et bilde, bruker vi gruppens profilbilde i stedet.`,
  Hd = `Når kategorien til begivenheten er satt til «Annen», blir begivenhetens synlighet betydelig redusert. Steam bruker kategoriene for å hjelpe med å lede begivenhetene til Steam-kunder. «Annen» er kategorien med minst innflytelse og blir vist til minst antall brukere.`,
  Ud = `Undertittelen eksisterer på %1$s av %2$s språk. Du bør vurdere å sørge for at hvert språk også har en oversatt undertittel.`,
  Wd = `Språkspesifikke bilder eksisterer på %1$s av %2$s språk. Dette kan fint ignoreres om bildene ikke trenger oversettelser. Det engelske bildet vises for språk uten egne bilder.`,
  Gd = `Tidspunktet der begivenheten skal bli synlig er justert til fortiden, så begivenheten blir synlig nå hvis du lagrer. Når den er synlig, kan ikke starttidspunktet endres – begivenheten kan ikke skjules igjen.`,
  Kd = `Det er lastet opp fremhevede bilder i butikken for denne begivenheten, men det fremhevede området brukes ikke. Det fremhevede området må brukes for å vise banneret på butikksiden din.`,
  qd = `Måladressen til salgssidens logo er ikke relativ til butikkens hjemmeside, så å trykke på logoen sender kunder til en ødelagt side. Den skal se ut som category/pins_pegs, ikke https://store.steampowered.com/category/pins_pegs.`,
  Jd = `Fant flere seksjoner av denne typen`,
  Yd = `Denne salgssiden inneholder minst en annen seksjon av samme type som denne seksjonen. Denne seksjonen er ment å bare brukes en gang på en enkelt salgsside. Er du sikker på at du trenger flere seksjoner av denne typen?`,
