  $m = `HEI, UTVIKLERE!`,
  eh = `Takk!`,
  th = `Steam-teamet`,
  nh = `Du mottar denne e-posten fordi du er med i en partnergruppe i Steamworks og denne meldingen er relevant for deg basert på grupperettighetene dine.`,
