  bh = `Velg fil`,
  xh = `Vis utvalgte utgivere`,
  Sh = `Det er valgfritt å filtrere til en liste med utgivere eller app-ID-er. Hvis ingen av disse er angitt, sammenligner vi innstillingene ovenfor med alle utgivere i Steamworks.`,
  Ch = `* Viser %1$s`,
  wh = `Vi bruker reservespråket %1$s, da %2$s, som er valgt i forhåndsvisningen, ikke har noe tekst i begivenhetens beskrivelse.`,
  Th = `Oversikt over synlighet`,
  Eh = `Basert på dine innstillinger blir begivenheten eller kunngjøringen vist på følgende steder`,
  Dh = `Standardsteder`,
  Oh = `Valgfrie steder`,
  kh = `Inntrykk`,
  Ah = `Butikk: På spillets butikkside`,
  jh = `Denne begivenheten vises på spillets butikkside under nyheter og begivenheter.`,
  Mh = `Tallet her viser antatt antall besøkende på butikksiden i tidsperioden der begivenheten vises.`,
  Nh = `Butikk: På siden med nylig oppdaterte spill`,
  Ph = `Hvis du bruker en synlighetsrunde når du har publisert begivenheten, vises begivenheten på siden over nylig oppdaterte for spillere som eier eller har spillet på ønskelisten.`,
  Fh = `Tallet her viser hvor mange brukere som eier eller har spillet på ønskelisten og kan se det på siden med nylig oppdaterte.`,
  Ih = `Nyheter: På spillets nyhetsside`,
  Lh = `Denne begivenheten vises i nyhetslisten, som er tilgjengelig ved å trykke «Vis relaterte nyheter» fra spillets butikkside.`,
  Rh = `Tallet her viser antatt mengde trafikk på spillets nyhetsside.`,
  zh = `Samfunn: I spillets samfunnssentral`,
  Bh = `Inkluderer spillets hovedsentral, samt fanene med nyheter og kunngjøringer som lenkes fra butikksiden.`,
  Vh = `Samfunn: I venners aktivitetskanal for spillere som følger spillet`,
  Hh = `Denne begivenheten kan vises i aktivitetskanalen for spillere som følger spillet.`,
  Uh = `Tallet her viser antall spillere som følger spillet.`,
  Wh = `Kommende:`,
  Gh = `Bibliotek: På startsiden i Steam-biblioteket (potensielt)`,
  Kh = `Spillere kan se denne begivenheten øverst på startsiden i biblioteket, avhengig av hvor mange andre spill en bestemt spiller eier og prioriteten i forhold til andre kunngjøringer eller oppdateringer.`,
  qh = `(avventer moderering)`,
  Jh = `Bibliotek: Fremhevet område på spillets bibliotekside`,
  Yh = `Hvis du laster opp et fremhevet banner, kan begivenheten/kunngjøringen vises rett nedenfor «Spill»-knappen på spillsiden i Steam-biblioteket.`,
  Xh = `Bibliotek: På spillets side i spillernes Steam-bibliotek`,
  Zh = `Begivenheten vises i aktivitetsdelen på spillets side i spillernes Steam-biblioteket.`,
  Qh = `Basert på antall spillere som eier spillet og kan se det i Steam-biblioteket.`,
  $h = `På workshop-siden`,
  eg = `Du kan også publisere denne begivenheten/kunngjøringen i spillets Steam Workshop. Hvis du vil gjøre dette, kan du bytte til fanen «Innstillinger» og velge «Publiser i workshopen i tillegg». Som standard vises ikke begivenheter/kunngjøringer i workshop-delen.`,
  tg = `Salgsbanner på Steam-produktside`,
  ng = `Banner på produktside er synlig fra %1$s frem til %2$s`,
  rg = `Du kan angi et salgsbanner under fanen «Salg», som gjør at fremhevede spill kan henvise til salget ved å vise det angitte banneret øverst på Steam-produktsiden sine. Dette er nyttig for Steam-kunder som oppdager en bestemt spillrabatt via en e-post om spill fra ønskelisten deres, eller når de finner ut om hovedsalget ved å bla gjennom butikken. Disse bannerne er kun synlige fra begynnelsen til slutten av begivenheten, eller i to uker, avhengig av hva som kommer først. Tidene for slike begivenheter er spesifisert under fanen «Innstillinger».`,
  ig = `Varsel: E-post til spillere som følger spillet, utvikleren eller utgiveren`,
  ag = `Dette inkluderer alle følgere av spillets tilhørende utvikler-, utgiver- og seriesider.`,
  og = `De følgende utvikler-, utgiver- eller serielenkene har ikke et synlig skaperhjem. Hvis du oppretter det, kan det hjelpe kundene med å forstå hva du tilbyr og gi dem mulighet til å se mer om dine begivenheter og nye spill: %1$s`,
  sg = `Nyheter: Spilleres personlige begivenhetskalender`,
  cg = `Denne begivenheten blir vist i den personlige nyhetssentralen for spillere som enten har spillet i biblioteket sitt, på ønskelisten sin, eller som følger spillet ditt.`,
  lg = `Varsel: Push-varsel til spillerne som har meldt seg på`,
  ug = `Antall spillere som har valgt å motta påminnelser om denne begivenheten (lastet ned til en ekstern kalender eller valgt å følge begivenheten).`,
  dg = `spillere som mottar en e-post`,
  fg = `Antatt antall e-poster som inkluderer denne begivenheten. Vi lager jevnlig en samling av utvalgte begivenheter for hver kunde. Dette avhenger av hver kundes innstillinger for e-post og kommunikasjon.`,
  pg = `spillere som mottar markedsføringsmeldinger`,
  mg = `Antatt antall spillere som vil se denne begivenheten dukke opp i en tilpasset markedsføringsmelding i Steam-klienten. Dette er et vindu som dukker opp når Steam-klienten startes opp, og viser relevante Steam-salg og interessante begivenheter.`,
  hg = `spillere som ignorerte begivenheten`,
  gg = `Antall spillere som har valgt å ignorerer denne begivenheten.`,
  _g = `Feil under lasting av begivenhet`,
  vg = `Se dokumentasjon`,
  yg = `Markedsføringsmelding om stor oppdatering – gjennomgang`,
  bg = `Når begivenheten er ferdig og ingen flere endringer er nødvendige, send den inn for gjennomgang for bruk i en markedsføringsmelding. Du kan gjerne publisere begivenheten til den store oppdateringen så snart den er klar. La det gå opptil %1$s virkedager for gjennomgang og godkjenning.`,
  xg = `Opprette følgende sak for å starte gjennomgangsprosessen.`,
  Sg = `Opprett gjennomgangssak`,
  Cg = `Saken er blitt sendt inn. Gå gjennom og oppdater informasjonen <1>her</1>.`,
  wg = `Oversikt`,
  Tg = `Synlighetsstart`,
  Eg = `Dette blir synlig de fleste steder så snart du publiserer.`,
  Dg = `Merk at nye innlegg gjennomgås av modereringsteamet vårt i den rekkefølgen de er publisert. Det kan oppstå en forsinkelse på minst 1 time før nyheter og begivenheter vises i Steam-biblioteket. Eventuelle endringer i eksisterende innlegg gjør at innlegget plasseres tilbake i modereringskøen.`,
  Og = `Eller erstatt innholdet i den eksisterende begivenheten`,
  kg = `Uvanlig. Dette gir deg muligheten til å forberede oppdateringer i en slags utkastbegivenhet og deretter erstatte innholdet i en eksisterende publisert begivenhet med innholdet i denne begivenheten. Denne begivenheten forsvinner, og innholdet erstatter den publiserte målbegivenheten. Innstillinger for begivenhetstype og synlighet oppdateres ikke i målbegivenheten.`,
  Ag = `Denne begivenheten ble klonet fra «%1$s»`,
  jg = `Erstatt den opprinnelige begivenheten`,
  Mg = `Innholdet i denne begivenheten erstatter innholdet i begivenheten som den opprinnelig ble klonet fra.`,
  Ng = `Merk: Den opprinnelige begivenheten må være publisert og synlig. Vi kan ikke erstatte den før den er offentlig synlig.`,
  Pg = `Denne handlingen trer i kraft umiddelbart. Dette erstatter innholdet til målbegivenheten, og blir umiddelbart synlig for brukere på Steam. Den gjeldende begivenheten forsvinner i denne handlingen.`,
  Fg = `Målbegivenhetens tittel: %1$s`,
  Ig = `Målbegivenhetens siste oppdatering: %1$s`,
  Lg = `Den som oppdaterte målbegivenheten sist: %1$s`,
  Rg = `Laster informasjon om publisert begivenhet`,
  zg = `Sjekk for å bekrefte at du forstår handlingen`,
  Bg = `Velg en nylig publisert og synlig begivenhet du vil erstatte`,
  Vg = `Erstatt valgt begivenhet`,
