  e_ = `Disse kringkasterne har tillatelse til å bli vist på begivenhets- og butikksiden, når de strømmer spillet under denne begivenheten.`,
  t_ = `Reklamesnutt`,
  n_ = `Foreldet: VOD-flyten er ikke lenger i bruk, etterlates i tilfelle vi må bruke gammel video. Denne videoen vises i kringkastingsspilleren før vanlige programmer. VOD må ha offentlige tillatelser (separat fra utgivelsesstatus).`,
