  P_ = `Slå på gjenstandsdropp for denne kringkastingen?`,
  F_ = `Utføres droppene manuelt?`,
  I_ = `Hvor mange minutter før man er berettiget til å motta droppet?`,
  L_ = `Valgfritt: Opprett en Steam-begivenhet med detaljer om droppene. Nyttig for salgsbegivenheter som ikke har en egen begivenhetsside.`,
  R_ = `Klankonto-ID`,
  z_ = `Klanbegivenhets-GID`,
  B_ = `Vis bredere avspillere`,
  V_ = `Når angitt vil dette fjerne venstre og høyre søyle fra avspilleren. Kun nyttig når det er en enkelt sending for begivenheten og søylene forstyrrer opplevelsen.`,
  H_ = `Slå på bred avspillermodus`,
  U_ = `Hvis tillatt, så dukker det opp en knapp for å vise/skjule samtalen. Når samtalen vises, går den tilbake til standard ikke-bred avspillermodus. Når samtalen lukkes, går den tilbake til bred avspillermodus.`,
  W_ = `Tillat vis/skjul samtale`,
  G_ = `Vis kunngjøringer av vinnere av gaveutdelinger`,
  K_ = `Angi gaveutdelings-ID`,
  q_ = `Hvis det finnes en gaveutdeling tilknyttet kringkastingen som kunngjør vinnere gjennom samtalen til kringkastingen, så kan det å angi gaveutdelingens GID gjøre at samtalemeldingene kan hentes selv om samtalen er lukket, og da kun se etter kunngjøringer for visningsformål.`,
  J_ = `Kringkastingens tittel`,
  Y_ = `Velg fra en liste over standardtitler som vises ovenfor direktesendingen på butikksiden, eller skriv inn en egendefinert tittel.`,
  X_ = `Skriv inn tittel`,
  Z_ = `Se dokumentasjon`,
  Q_ = `Bilde til kringkasting`,
  $_ = `Kringkastingens bildeinnstillinger`,
  ev = `Vis høyre og venstre banner i stedet for spillkapsel.`,
  tv = `Når dette er slått på, vises banneret i Steam-butikken i stedet for spillkapslene. Dette er nyttig hvis banneret har mer relevant informasjon om begivenheten enn en bestemt appkapsel. Det er også nyttig hvis flere spill strømmes over tid, og du kun vil vise et enkelt element for begivenheten.`,
  nv = `Liste over tillatte kringkastere`,
  rv = `Angitt Steam-ID er ugyldig. Det skal være en 64-bit numerisk verdi.`,
  iv = `Kringkastingens bakgrunn`,
  av = `Bakgrunnsovergang (indre farge)`,
  ov = `Bakgrunnsovergang (ytre farge)`,
  sv = `Kunne ikke laste inn brukerinformasjon`,
  cv = `Valgfri innstilling som gjør det mulig å markere en strøm med et bestemt talespråk for seerne. Dette er nyttig hvis det er flere strømmer for begivenheten på forskjellige språk, så vi kan velge den beste standardstrømmen til brukere basert på språket deres.`,
  lv = `Prioritet`,
  uv = `Angi hvilken prioritet denne kringkastingen har i forhold til andre kringkastinger. Kringkastinger med høyere prioritet velges fremfor de med lavere prioritet. Hvis flere kringkastinger har samme prioritet, velges en av dem tilfeldig som standard.`,
  dv = `Primær (høyest)`,
  fv = `Fremhevet (høy)`,
  pv = `Standard (middels)`,
  mv = `Generell (lav)`,
  hv = `Sendingstype`,
  gv = `Beskriver om innholdet sendes direkte eller om det allerede er innspilt. For sistnevnte beskriver det også om det er første gang det sendes på plattformen eller om det er en reprise.`,
  _v = `Ukjent/uspesifisert`,
  vv = `Direktesending`,
  yv = `Premiere`,
  bv = `Reprise`,
