  wv = `Kringkasterkontroller`,
  Tv = `Kamp-ID`,
  Ev = `Kontroller ble oppdatert`,
  Dv = `Kunne ikke oppdatere, prøv igjen senere`,
  Ov = `Kringkastingen ble stoppet`,
  kv = `Kringkasting kunne ikke stoppes, prøv igjen senere`,
  Av = `Stopp kringkasting`,
  jv = `Om dette spillet`,
  Mv = `Butikkside`,
  Nv = `Rapporter kringkasting`,
  Pv = `Rapporter denne kringkastingen`,
  Fv = `Ofte stilte spørsmål om kringkasting`,
  Iv = `Se ofte stilte spørsmål om kringkasting`,
  Lv = `Send tilbakemeldinger`,
  Rv = `Rapporter denne gjenstanden`,
  zv = `Beskriv hvordan denne gjenstanden bryter Steams vilkår for bruk. Ta med all relevant informasjon eller lenker. Innlevering av denne rapporten kan ikke omgjøres.`,
  Bv = `Tidsplan`,
  Vv = `Planleggingsverktøy`,
  Hv = `Lag en tidsplan/tidslinje, som skal vises på begivenhetssiden?`,
  Uv = `Legg til programpost`,
  Wv = `Fjern denne posten`,
  Gv = `Innebygd forhåndsvisning av tidsplan`,
  Kv = `Forklaring av programposttyper`,
  qv = `Type`,
  Jv = `Formål`,
  Yv = `Konkurransekamp`,
  Xv = `Dette er en konkurransekamp mellom to eller flere personer/lag. Etter kampen kan du oppdatere resultatet og inkludere opplysninger om vinneren.`,
  Zv = `Kringkasting`,
  Qv = `Dette forteller brukerne at de kan se en direktesending på Steam eller et annet sted i denne perioden.`,
  $v = `Spill`,
  ey = `Dette ber brukerne om å delta i begivenheten på det angitte tidspunktet ved å starte opp spillet og spille sammen.`,
  ty = `I virkeligheten`,
  ny = `Brukes når programdelen finner sted og kun er tilgjengelig for folk som er til stede under begivenheten, og ikke kan direktesendes. Merk: Det er kanskje best å ikke inkludere dette i tidsplanen, da Steam-fans ikke vil kunne delta.`,
  ry = `Starttidspunkt`,
  iy = `Angitt i minutter fra begynnelsen av begivenheten.`,
  ay = `Minutter`,
  oy = `Denne programposten er blitt endret fra standard. Er du sikker på at du vil slette den? Denne handlingen kan ikke angres.`,
  sy = `Nåværende serier`,
  cy = `En serie binder flere relaterte begivenheter sammen med et felles markedsføringsbilde og fargetema. Dette kreves ikke for at begivenheter skal vises på programmet. Eksempler på disse er «hovedscenen» og «kunstserie».`,
  ly = `Ingen serier angitt.`,
  uy = `Legg til serie`,
  dy = `Legger til en ny serie for å gruppere og markedsføre begivenheter på programmet.`,
  fy = `Slett serie`,
  py = `Er du sikker på at du vil slette serien?`,
  my = `Umerket serie %1$s`,
  hy = `Legg til begivenheter spesifikt for dette lydsporet. De er kun gyldige hvis de publiseres, begynner og slutter innenfor tidsperioden og samsvarer med typen begivenhet som er tillatt i programmet.`,
  gy = `Salgsavtaler`,
  _y = `Før du kan bruke salgsverktøyet, må du godta følgende krav:`,
  vy = `Jeg forstår at salgssiden må tydelig beskrive gruppen eller individene som er ansvarlige for å organisere salget eller begivenheten.`,
  yy = `Jeg forstår at jeg ikke kan garantere deltakere en bestemt grad av synlighet på Steam, og at jeg ikke kan ta betalt for plassering på siden.`,
  by = `Jeg forstår at Valve forbeholder seg retten til å endre en salgsside, inkludert, men ikke begrenset til, synligheten til spill eller sendinger på siden, eller tekst og bilder som beskriver begivenheten.`,
  xy = `Jeg forstår at Valve bestemmer hvilke begivenheter som fremheves i Steam-butikken og at begivenheten min ikke nødvendigvis blir fremhevet.`,
  Sy = `Jeg forstår at jeg kun kan legge til spill på en salgsside som utvikleren eller utgiveren har gitt tillatelse for. Spillets utviklere får se at spillet er med i salget mitt så snart jeg legger det til på siden her.`,
  Cy = `Jeg godtar alle reglene slik de er fastsatt i %1$s.`,
  wy = `Se %1$s for mer informasjon om design og opprettelse av salgssider.`,
  Ty = `dokumentasjonen`,
  Ey = `Kontaktperson`,
  Dy = `Hvis spillutviklere, utgivere eller medier har spørsmål om denne begivenheten, hvem bør de ta kontakt med?`,
  Oy = `skriv inn navn`,
  ky = `skriv inn e-postadresse`,
  Ay = `Gå gjennom retningslinjer og kontaktinfo`,
  jy = `Retningslinjene ble gjennomgått og godtatt %1$s.`,
  My = `dokumentasjonen om utvikler- eller utgiversalg`,
