  Iy = `dokumentasjonen om temasalg`,
  Ly = `Retningslinjer gjennomgått og godtatt.`,
  Ry = `Oppgi navnet og nettadressen til arrangøren av denne begivenheten. Disse opplysningene vises øverst på salgssiden. De er nødvendige og kan redigeres når som helst.`,
  zy = `Arrangører`,
  By = `Oppdater arrangører`,
  Vy = `Angi arrangørinfo`,
  Hy = `Skriv inn navnet på virksomheten som arrangerte denne begivenheten. Lenken kan være til arrangørens skaperside på Steam eller til et eksternt nettsted. Det engelske navnet er påkrevd, men navnet kan eventuelt også lokaliseres.`,
  Uy = `Disse opplysningene vises på salgssiden din som følger:`,
  Wy = `Legg til en arrangør`,
  Gy = `Arrangørnavn`,
  Ky = `Nettadresse`,
  qy = `Lokalisert bildegruppe`,
  Jy = `Hovedbilde til lokalisert bildegruppe`,
  Yy = `Dette brukes automatisk som standardbilde, hvis det ikke er en lokalisert versjon på et språk, som brukeren har valgt. Det kan være en versjon uten språk eller et vanlig språk blant kundene dine.`,
  Xy = `Hvis bildet inneholder tekst, kan du laste opp lokaliserte versjoner av bildene her for alle språkene Steam støtter. Steam viser automatisk det aktuelle lokaliserte bildet til kunder.`,
  Zy = `Last opp bilder med navneendelsen fra Steams %1$s, så vi automatisk kan tildele dem det riktige språket.`,
  Qy = `Web API-språk`,
  $y = `Bilder`,
  eb = `Bruk området nederst til å laste opp nye bilder, så de er tilgjengelige fra alle begivenhetene. Du kan deretter dra og slippe dem fra denne delen eller trykke for å sette inn bilder i innlegget, enten i full størrelse eller miniatyrstørrelse.`,
  tb = `Søk etter bilder …`,
  nb = `Velg filer`,
  rb = `Ingen fil valgt`,
