  Rb = `Ugyldig`,
  zb = `Feil størrelse`,
  Bb = `Trykk nedenfor for å beskjære og endre størrelsen på bildet til %1$sx%2$s.`,
  Vb = `Det valgte bildet er for lite til denne bildetypen. Det må være minst %1$sx%2$s.`,
  Hb = `Rediger hovedbanner`,
  Ub = `Beskjær bilde`,
  Wb = `Beskjær bilde – %1$sx%2$s`,
  Gb = `Dra i hjørnene eller kantene på det blå feltet, og velg området av bildet du vil bruke til begivenheten eller kunngjøringen.`,
  Kb = `Åpne bilderedigering`,
  qb = `Beskjær og fortsett`,
