  Xb = `Bildeoppløsningen må være akkurat %1$sx%2$s.`,
  Zb = `Bilder som lastes opp sammen, må ha samme oppløsning.`,
  Qb = `Denne filtypen støttes ikke for denne ressursen.`,
  $b = `Overskrider maksimal filstørrelse på %1$s`,
  ex = `Endelig bilde`,
  tx = `Dette fjerner alle oversatte bilder av denne typen. Du må lagre begivenheten etterpå for at det skal tre i kraft. Er du sikker?`,
  nx = `[sist oppdatert: %1$s]`,
  rx = `Støttede språk`,
  ix = `Ytterligere språk`,
  ax = `Velkommen til den åpne betaversjonen for Steam-begivenheter`,
  ox = `Se dokumentasjonen for detaljer og advarsler om hvordan begivenhetene og kunngjøringene fungerer i betaversjonen.`,
  sx = `Tilbakemelding: Har du en feil du vil rapportere, en kommentar eller et spørsmål? Skriv gjerne en melding i %1$s eller kontakt din lokale Steam-kontoadministrator.`,
  cx = `Steamworks-forumet`,
  lx = `Det kommer mer snart`,
  ux = `I den åpne betaen er denne visningen kun synlig for deg og ditt team. Steam-kunder vil fremdeles se begivenheter og kunngjøringer i den eksisterende visningen.`,
  dx = `Tips og spesifikasjoner`,
  fx = `Last ned designmaler for begivenhet`,
  px = `Usikker på hva som trengs? Se noen eksempler.`,
  mx = `%1$s x %2$s px (bredde x høyde) %3$s`,
  hx = `Bildestørrelse`,
  gx = `Logoer og tekst bør sentreres og være innenfor de midterste 800 pikslene.`,
  _x = `Logo`,
  vx = `Du kan navngi bildefilene så de ender på språknavn for å automatisk kategorisere dem som det aktuelle språket (f.eks. «header_french.jpg»). %1$s for en liste over språk som støttes.`,
  yx = `Lokalisering`,
  bx = `Last opp flere filer ved å dra dem inn i feltet nedenfor eller ved å trykke «Velg fil».`,
  xx = `Last opp bilder`,
  Sx = `Behandle bilde (1)`,
  Cx = `Behandle bilder (%1$s)`,
  wx = `Gi informasjonssiden et rikt toppbilde for å kommunisere temaet eller kjernen i oppdateringen eller kunngjøringen. Det er viktig å laste ned malene (lenke ligger øverst på siden) for å sørge for at toppbildet er utformet riktig for de ulike stedene det blir brukt.`,
  Tx = `Forhåndsvisning av informasjonssiden:`,
  Ex = `Forhåndsvisning av begivenhetens vindu:`,
  Dx = `Dette bildet vises i sidepanelet ved siden av kringkastingen.`,
  Ox = `Viktige begivenheter eller kunngjøringer kan inkludere et bannerbilde som vises på butikksiden så lenge begivenheten varer. Bildet i dette banneret er separat fra andre steder i butikken. Disse bannerne må godkjennes av Valve, så snakk med kontaktpersonen din hos Valve før du laster opp.`,
  kx = `Planlegg å ta med en kort, fengende beskrivelse av begivenheten som kommer tydelig frem på det fremhevede banneret, så spillere lett kan se hva som gjør begivenheten spennende.`,
  Ax = `Du kan bruke hele bildeområdet og ha med din egen beskrivelse av oppdateringen eller begivenheten inni bildet.`,
  jx = `Dette er en mobilversjon av det fremhevede området i butikken, og brukes når en bruker ser på det fremhevede området på en smal skjerm.`,
  Mx = `Dette bildet vises som bakgrunn på salgssiden. Du kan lage dette som ett stort bilde, eller lage en rute og sette det til et gjentakende mønster.`,
  Nx = `Viktig innhold bør plasseres i de midterste 940 pikslene av bildet. Bildet kan spre seg ut på sidene og ned på siden som du vil. Generelt bør du tone ut bildet til en heldekkende farge på sidene og bunnen, og deretter kan du velge samme bakgrunnsfarge på salgssiden. Bildet må være under 4\xA0MB.`,
  Px = `Last ned alle maler for salgssider (PSD-filer)`,
  Fx = `Salgets bakgrunnsbilde fungerer bra sammen med salgsidens logo angitt nedenfor. Hvis disse brukes sammen, kommer logoen til å flyte over bakgrunnen.`,
  Ix = `Maler`,
  Lx = `Dette bildet legges over bakgrunnen øverst på siden. Hvis du vil ha bilder oversatt, kan du sende en .psd-fil på e-post til kontakten din i Valve.`,
  Rx = `Hvis banneret er angitt, dukker det opp på butikksiden for alle spillene som er en del av dette salget. Dette banneret varer like lenge som salget, opptil to uker. Merk at banneret må godkjennes av Valve før bruk, og det kan ikke animeres.`,
  zx = `Denne versjonen vises kun når sideoppløsningen forminskes til mobilskjermer.`,
  Bx = `Du kan også oppdatere hovedbanneret med markedsføring for oppdateringen, kunngjøringen, sesongen eller annen begivenhet. Gå til fanen «Grafiske elementer» i butikkadministrasjonen for å gjøre dette.`,
  Vx = `Design`,
  Hx = `Bildestørrelse`,
  Ux = `Bruk`,
  Wx = `Påkrevd`,
  Gx = `Valgfritt`,
  Kx = `Dette inneholder vanligvis bilder eller merkevarer som representerer begivenheten din, pluss eventuelt en kort melding du har lyst til å få frem. Steam inkluderer automatisk spillets navn og ikon ved siden av bildet i noen sammenhenger, men du må kanskje inkludere spillets logo i forsidebildet også siden dette bildet brukes når begivenheten din deles på sosiale medier.`,
  qx = `Det vises på butikksiden under nylige kunngjøringer, på listen over begivenheter og kunngjøringer, og på informasjonssiden i biblioteket. Bildet brukes til å representere begivenheten når den deles på sosiale medier. Det brukes som en lenke til begivenheten/kunngjøringen og kan vises sammen med innhold fra flere andre spill, så bildet bør være tydelig og gjenkjennelig.`,
  Jx = `Dette bildet inneholder vanligvis design og merkevarer som representerer utgiveren, utvikleren eller serien. Steam inkluderer automatisk profilbildet ditt ved siden av dette bildet i enkelte sammenhenger.`,
  Yx = `Det vises på steder på Steam der denne skapersiden vises, og brukes for å representere begivenheten når den deles i sosiale medier. Bildet bør være tydelig og gjenkjennelig.`,
  Xx = `Bannerbilde for lenke til årets beste på Steam-listene`,
  Zx = `Plasseres i salgets krysspromoteringsseksjoner, slik som på tilbudssiden, istedenfor salgssidens logo. Hvis denne logoen ikke behøver lokalisering, last den opp én gang, på engelsk, så brukes den av alle språkene.`,
  Qx = `En logo som gjengis øverst på salgssiden over bakgrunnsbildet. Dette bildet bør inneholde begivenhetens logo, datoer og eventuelt et slagord, og det bør ha en gjennomsiktig bakgrunn.`,
  $x = `Se dokumentasjonen`,
  eS = `Bildeforhåndsvisning`,
  tS = `Last opp bilde`,
  nS = `Opplastede språk`,
  rS = `Merk dette bildet som et annet språk`,
  iS = `Åpne dette bildet i et nytt vindu`,
  aS = `Slett dette bildet kun for dette språket`,
