  sS = `Bruk opplastingen ovenfor`,
  cS = `Intet språk`,
  lS = `Velg fil`,
  uS = `Fjern bilde fra liste`,
  dS = `Fjern bildet fra begivenhetens tittelbilde for %1$s? Dette sletter ikke det aktuelle bildet, men tar bort tilknytningen til begivenheten.`,
  fS = `Den røde firkanten som vises på bildet, angir området der logoer og eventuell tekst bør passe innenfor. Det angitte delområdet vises i noen sammenhenger, slik som i lister.`,
  pS = `Eksempel på kompakt visning`,
