  TS = `Begivenhetens dato`,
  ES = `Begivenhetens detaljer og beskrivelse`,
  DS = `Bildet må være på minst 1920x800 (høyde x bredde). Det kan være større i både høyden og bredden.`,
  OS = `Redigere applikasjonens metadata`,
  kS = `Gir tillatelse til å laste opp depoter, teste Steamworks-funksjoner, definere pakker, prestasjoner, ledertavler, legge ut samlekort osv. Gir også administratortilgang og angivelse for Steam-samfunnet for alle applikasjoner i gruppen.`,
  AS = `Publisere applikasjonsendringer til Steam`,
  jS = `Gir tillatelse til å publisere endringer gjort i seksjonen Tekniske verktøy > Rediger Steamworks-innstillinger på Steamworks-utviklersiden til produktet.`,
  MS = `Se feildata`,
