  HS = `Behandle signering`,
  US = `Kan behandle digital signering for produktet. Dette aktiverer behandling av antijuks- og SDK Auth-innstillinger for applikasjonen.`,
  WS = `Behandle CD-nøkler`,
  GS = `Redigere applikasjonens markedsføringsdata`,
  KS = `Gir tillatelse til å redigere og publisere butikksidedata, som for eksempel spillbeskrivelse, markedsføringsbilder og videoer. Gir også tilgang til markedsføringsverktøy som synlighetsrunder.`,
  qS = `Redigere oversettelsesdata for butikken`,
  JS = `Gir tillatelse til å redigere data på innstillingsfaner i butikken som inkluderer ett eller flere felt som kan lokaliseres, slik som produktbeskrivelse og grafiske elementer. Gir ikke tillatelse til å publisere, eller tilgang til markedsføringsverktøy som synlighetsrunder. Merk: Dette er en undergruppe av funksjonaliteten «Redigere applikasjonens markedsføringsdata».`,
  YS = `Økonomi-/workshopkundestøtte`,
