  nC = `Lar brukeren kringkaste offisielle direktesendinger for applikasjonene.`,
  rC = `Se trafikkdata for markedsføring`,
  iC = `Kan se trafikkdata om navigasjon fra Steam-butikken, samfunnet og plattformen for produktet ditt.`,
  aC = `Behandle brukere`,
  oC = `I hele utgiveren: Disse brukerne kan legge til og forfremme andre brukere`,
  sC = `Fullmakt`,
  cC = `I hele utgiveren: Disse brukerne kan endre betalingsdetaljer (dvs. bankkonto- og skatteopplysninger) og overføre åndsverksrettigheter`,
  lC = `Se finansiell informasjon (i hele utgiveren)`,
  uC = `I hele partneren: Disse brukerne kan se salgsrapporter og finansielle data for alle appene som administreres av denne partneren`,
  dC = `Godkjenne lommebokfinansiering`,
  fC = `Disse brukerne kan godkjenne kundetransaksjoner for lommebokfinansiering`,
  pC = `Behandle lisensierte områder`,
  mC = `Disse brukerne kan se og behandle områdeopplysninger, lisenser og aktiviteter for lisensierte områder`,
  hC = `Motta Steamworks-kommunikasjon`,
  gC = `Disse brukerne mottar e-poster om kommende kampanjer, målrettede begivenheter og kunngjøringer om nye funksjoner på Steam.`,
  _C = `Denne brukeren er blitt tilsendt en invitasjon til å motta tillatelse for Steamworks-kommunikasjon, men har ikke godtatt den ennå.`,
  vC = `Slå på salgsside`,
  yC = `Salgssider krever at du oppgir følgende:`,
  bC = `Et pyntenavn som vil vises på slutten av nettadressen. Uten dette vil salgssiden din ikke være tilgjengelig for kunder på Steam.`,
  xC = `Må angi starttidspunkt og sluttidspunkt. Hvis du ikke angir disse riktig, vil både sporing av statistikk og bilder på produktsiden ikke fungere riktig.`,
  SC = `Starttidspunkt for salg`,
  CC = `Sluttidspunkt for salg`,
  wC = `Slå på oppdateringsside`,
  TC = `Oppdateringssiden krever at du angir et navn som vises på slutten av nettadressen i butikken. Kunder på Steam får se denne oppdateringssiden på den nettadressen.`,
  EC = `Slå på redigeringsverktøyet for salgssider for denne begivenheten?`,
  DC = `Slå på en oppdateringsside for denne begivenheten?`,
  OC = `Velg fra en liste med standardtitler:`,
  kC = `Standardtittel brukes ikke på grunn av egendefinert tittel på gjeldende språk eller engelsk`,
  AC = `Eller overstyr med egendefinert tittel`,
  jC = `Angitte egendefinerte titler:`,
  MC = `(Valve) Last opp bilder med egendefinerte titler. Tittelteksten vil være bildets alt-tekst.`,
  NC = `Vis et spesielt overlegg på toppbildet (f.eks. en komponent slik som Steams spøkelseshus til halloween 2019)`,
  PC = `Vis overlegg med begivenhetens tittel og beskrivelse på toppbildet`,
  FC = `Pikselforskyvning`,
  IC = `Pikselforskyvning er slått av siden logo for salgsside er på plass. Logoen justerer pikselforskyvningen automatisk.`,
  LC = `Dette er antall piksler å flytte innholdet på salgssiden ned for å gi plass til tittel og datoer i salgssidens bakgrunnsbilde. Det skal ikke være nødvendig å justere mer med mindre man prøver å få til noe helt spesielt.`,
  RC = `Standard (og maks) verdi her bør være %1$s`,
  zC = `Det sørger for at salgssiden fungerer ordentlig på Steam Deck eller nettbrett.`,
  BC = `(Valve) Begrens denne siden til app-eiere?`,
  VC = `Det kreves et abonnement for å få tilgang til denne siden. Ikke-eiere omdirigeres (f.eks. til en kjøpsside).`,
  HC = `Påkrevde app-ID-er`,
  UC = `Tillat kun eiere av disse applikasjonene (eller pakker fra den andre listen) å se denne siden.`,
  WC = `Påkrevde pakke-ID-er`,
  GC = `Juster kapseloppsett til å vise en «Legg til i bibliotek/Spill nå»-knapp istedenfor priser og «Legg i handlevogn»-knappen.`,
  KC = `Nettadresse til omdirigering`,
  qC = `Ikke-eiere omdirigeres til denne siden.`,
  JC = `Bruk abonnementsoppsett`,
  YC = `Tillat kun eiere av disse pakkene (eller applikasjoner fra den andre listen) å se denne siden.`,
  XC = `Advarsel: Valve har ikke aktivert salgsfunksjonen for denne begivenheten. Kun Valve kan aktivere salgsfunksjonen i den lukkede betaen. Henvend deg til kontaktpersonen din hos Valve for å be om å få aktivert begivenhetens salgsside.`,
  ZC = `(Valve) Begrens denne siden til applikasjonsredaktører?`,
  QC = `Gir kun tilgang til siden for de som har redigeringstillatelse for et spill på denne siden.`,
  $C = `Kringkasting/direktesending`,
  ew = `Bruk kringkastingsfanen til å konfigurere kringkastingsinnstillinger for dette salget.`,
  tw = `Kringkasting er slått av i dette salget.`,
  nw = `Bruk kringkastingsfanen til å slå på kringkasting i dette salget. Du kan tilpasse kringkastingens virkemåte på denne siden etter at du har slått det på.`,
  rw = `Inkluder kun spesifikt tillatte kringkastinger i kringkastingsfanen.`,
  iw = `Som standard viser Steam automatisk direktesendinger forbundet med ethvert spill som vises på denne salgssiden. Du trenger ikke gjøre noe mer hvis dette gir mening for dette salget. Men hvis du vil styre hvilke direktesendinger som vises på salgssiden, kan du slå på dette og velge spesifikke kringkastere i kringkastingsfanen.`,
