  lw = `Behandle egendefinerte bakgrunnstiler`,
  uw = `Opprett egendefinerte bakgrunnsstiler for seksjoner i dette vinduet. Disse stilene kan brukes for enhver seksjon på denne siden. Når en stil endres her, oppdateres den automatisk for alle seksjoner som bruker den stilen. Dette gjør at du kan kontrollere utseendet til flere seksjoner samtidig og holde dem samsvarende.`,
