  xw = `Legg inn produkter til redigering`,
  Sw = `Her kan du angi en liste med ID-er for å avgrense hvilke produkter som redigeres når du legger til eller fjerner etiketter. Dette er hovedsakelig utformet for klipp-og-lim av produktlister.`,
