  sT = `Dette er en liste over alle lenkede produkter som er tilknyttet salget og stemmer overens med filteroppsettet nedenfor.`,
  cT = `Filtrerte produkter – %1$s`,
  lT = `Dette er en liste over alle produktene som IKKE stemte overens med filteret, og som derfor ikke vises. Dette er nyttig for å feilsøke hvorfor et bestemt produkt ikke vises i en seksjon.`,
  uT = `Ubrukte produkter – %1$s`,
  dT = `Dette er en liste over alle lenkede produkter i salget som for øyeblikket ikke er plassert i noen seksjon, enten eksplisitt eller på grunn av et filter. Dette er nyttig for å sørge for at alle elementene er synlige i et salg, samt å utforske grupperinger av ubrukte produkter.`,
  fT = `Vis oversikt over etiketter`,
  pT = `Skjul oversikt over etiketter`,
  mT = `Lenkede gjenstander utgjør et utvalg av produkter. Disse er tilknyttet attributter som kan legges til i salget via filtre som velger hvilke produkter som samsvarer med et definert kriterium. Merk at disse produktene faktisk ikke er en del av salget og ikke er synlige for brukere før de er blitt inkludert i en fane eller en salgsseksjon gjennom et filter.`,
  hT = `Dette viser en liste over alle etiketter som de samsvarende produktene inneholder, samt hvor mange det er av hver. Dette er nyttig for å finne ut om det kan være andre tilgjengelige inndelinger av etiketter. Hver etikett kan velges for å se hvilke produkter på listen som inneholder den tilknyttede etiketten.`,
  gT = `Det er ikke blitt konfigurert noen filtre. Alle lenkede produkter inkluderes.`,
  _T = `Denne seksjonen er blitt konfigurert til å vise produkter basert på et filter som brukes på alle lenkede produkter i salget. Men dette filteret er ikke blitt konfigurert. Trykk på knappen nedenfor for å konfigurere filteret.`,
  vT = `Rediger filter`,
  yT = `Dette gjør det mulig å redigere filteret tilhørende denne seksjonen. Filteret brukes til å bestemme hvilke lenkede produkter i salget som vises i denne seksjonen.`,
