  BT = `Salgssidens pene ID/URL`,
  VT = `Dette brukes på slutten av salgssidens nettadresse når kunder finner den fra skaperstartsiden. Ikke bruk mellomrom, da URL-kodingen gjør den vanskeligere å lese. Bruk heller «_». Dette feltet godtar kun bokstaver, tall, «_» og «-». Eksempel: Halloween2019, Valentines, BestSaleEver`,
  HT = `Oppdateringssidens tilpassede ID/URL`,
  UT = `Dette brukes på slutten av butikksidens nettadresse og leder kunder til denne oppdateringssiden. Ikke bruk mellomrom, da URL-kodingen gjør den vanskeligere å lese. Bruk heller «_». Dette feltet godtar kun bokstaver, tall, «_» og «-». Eksempel: Halloween2019, Valentines, BestSaleEver`,
