  YD = `Viser en karusell med alle skaperlistene, som definert i seksjonen for behandlede lister i skapersideinnstillinger.`,
  XD = `Kuratoranbefalinger og -lister`,
  ZD = `Kontrollerer hvor kuratoranbefalinger eller fremhevede lister vises på siden. Som standard ser brukere som følger Steam-kuratorer den fulgte kuratorens anbefalinger om spill som er med i salget nederst på salgssiden. Dette lar deg bestemme hvor denne seksjonen vises.`,
  QD = `Viser kuratoranbefalinger og lister. Henter automatisk lister fra Steam-brukerens fulgte kuratorer og de fremhevede listene som er på Steam-brukerens språk.`,
  $D = `Valgfritt: Visningens starttidspunkt`,
  eO = `Du kan velge å angi et starttidspunkt for når anbefalingen skal vises, noe som kan gi kuratorer litt tid til å sette opp listene sine før de blir synlige. Dette må være mellom begivenhetens start- og sluttidspunkt.`,
  tO = `Vis liste med kuratoranbefalinger:`,
