  rO = `Velg en liste som skal vises`,
  iO = `Kuratorer kan lage en liste over spill fra salget. I denne dialogboksen kan du velge fritt mellom en eller flere lister å vise på siden. Listene vises for alle Steam-brukere som besøker siden.`,
  aO = `Kunne ikke velge kurator. Salget må være synlig og ha startet.`,
  oO = `Faner`,
