  cO = `Faneknapper`,
  lO = `Valgfri seksjon som bare er nyttig om det allerede finnes en fane. Den er nyttig å plassere nederst på siden, så fanene plasseres som knapper for enkel navigering for brukere som muligens har oversett fanene på siden.`,
  uO = `Flervalgsspørsmål`,
  dO = `En seksjon som lar deg sette opp noen quiz-lignende flervalgsspørsmål kundene dine kan oppleve.`,
  fO = `Smartseksjon i poengbutikken`,
  pO = `Denne seksjonen trenger en kategorimerkelapp for å fungere. Kategorimerkelappen brukes til å automatisk hente gjenstandene med aktuell merkelapp fra poengbutikken og vise dem i denne seksjonen.`,
  mO = `Klasse av samfunnsgjenstander`,
  hO = `Begrenser alle viste gjenstander fra poengbutikken til denne klassen. Valget er påkrevd.  Merk: Profilmodifikasjon er også kjent som spillprofil.`,
  gO = `Kategorimerkelapp i poengbutikken`,
  _O = `Angi hvilken kategorimerkelapp du vil bruke til å hente gjenstander fra poengbutikken. Denne merkelappen er sannsynligvis begivenhetens påmeldingsnavn, f.eks. sale_halloween_2022.`,
  vO = `Oppdagelseskø`,
