  eH = `Valgfri ressurs. Hvis den brukes, vises den til brukeren FØR de oppnår merket. Dette er nyttig når man øsnker å skjule spesifikke detaljer om merket før det anskaffes. Ressursen bør være 160 x 160 piksler.`,
