  nY = `Navnet på denne fasetten. En fasett er en gruppe relaterte innstillinger som brukeren kan trykke på for å filtrere spillene som vises i denne seksjonen. F.eks. «sjanger».`,
  rY = `Fyller automatisk ut fasettene og fasettverdiene basert på kategorier for butikkmerkelapper, som f.eks. «sjanger» og «visuell stil og synsvinkel». Etter den automatiske genereringen kan du manuelt endre hver fasett og fasettverdi etter behov.`,
