  cY = `Sorter fasettverdier innenfor hver fasett i alfabetisk rekkefølge.`,
  lY = `Sorter fasettverdier innenfor hver fasett i synkende rekkefølge etter antall gjenstander som samsvarer med dem. For eksempel: Under en fasett kalt «sjanger», vises «rollespill» før «strategi» hvis det er flere rollespill i denne seksjonen.`,
